def moyenne_classe(bulletins):
    total = 0
    for eleve in bulletins:
        total = total + eleve["moyenne"]
    return total / len(bulletins)

classe = [
    {"nom": "Ana", "moyenne": 14.3},
    {"nom": "Jean", "moyenne": 9.3},
    {"nom": "Marie"},
]
print(moyenne_classe(classe))
